import 'package:flutter/material.dart';
class AppAsyncView extends StatelessWidget { const AppAsyncView({super.key,required this.child,required this.isLoading,required this.error,required this.onRetry}); final Widget child; final bool isLoading; final Object? error; final VoidCallback onRetry; @override Widget build(BuildContext context) { if(isLoading)return const Center(child:CircularProgressIndicator()); if(error!=null)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.error_outline,size:48),const SizedBox(height:12),const Text('حدث خطأ، حاول مرة أخرى'),TextButton(onPressed:onRetry,child:const Text('إعادة المحاولة'))])); return child; } }
